-- ============================================================================
-- 52_map_products_to_correct_categories.sql
--
-- Фаза 5, стъпка „продукт по продукт": 4208 поправки на категории, получени от
-- индивидуален преглед на ВСИЧКИТЕ 7 371 видими и 14 565 невидими-но-застрашени
-- продукта срещу речника от 222 видими категории.
--
--   • 1175 намерени при обхода на ВИДИМИТЕ продукти — каталогът се оправя веднага
--   • 3033 намерени при обхода на НЕВИДИМИТЕ-но-застрашени — в категория с
--     show_flag, но без наличност или снимка; всеки от тях става видим сгрешен
--     продукт в деня, в който достави. Затова се поправят сега, в същия скрипт.
--
--   Разделянето е по това КОЙ обход ги е намерил, не по състоянието днес:
--   наличностите се менят непрекъснато. Към 2026-09-21 живото разпределение на
--   същите 4 208 продукта е 1 158 видими / 3 050 невидими. Скриптът не зависи
--   от това — той мести по id.
--
-- ЧИСТ SQL — без psql meta-команди, работи и в GUI клиент.
--
-- ⚠️ РЕДЪТ Е ВАЖЕН: първо се деплойва кодът (V37 + защитите в sync сервизите),
--    чак после се пуска този скрипт. Разпределение на 4 146-те поправки по
--    доставчик и какво прави всеки sync с категорията на СЪЩЕСТВУВАЩ продукт:
--
--      ASBIS  2 968 — AsbisSyncService:663 презаписва винаги, когато мапингът
--                     от feed-а успее
--      MOST     907 — MostSyncService:1018 презаписва БЕЗУСЛОВНО при всеки прогон
--      VALI     312 — ValiSyncService:990 задава категория само при създаване →
--                     тези биха оцелели и без кода, но флагът се вдига и за тях
--      TEKRA      9 — TekraSyncService:1124 и :1375 презаписват БЕЗУСЛОВНО
--      без platform 2 — не идват от feed, не са застрашени
--
--    Без кода ~3 884 от 4 198 поправки се губят до 24 часа.
--
-- МЕХАНИЗЪМ: `manually_categorized = true` (колоната от V37). Огледален на
--    `manually_hidden` от фаза 1 — sync-ът чете флага и прескача presetването
--    на категория. Смяна на категория през админ панела също го вдига
--    (ProductService.applyAdminCategory).
--
-- ДЪРВОТО НЕ СЕ ПИПА: не се създават, трият или местят категории; `sort_order`,
--    родители и нива остават непокътнати. Само `products.category_id`.
--
-- ОБРАТИМОСТ: оригиналната категория се пази в `category_id_pre_phase5`
--    (колоната от скрипт 48). Откат в края на файла.
--
-- Дата: 2026-09-18
-- ============================================================================

SET lock_timeout = '10s';
SET idle_in_transaction_session_timeout = '60s';
SET statement_timeout = '300s';


-- ─── СЕКЦИЯ A: предпазител ПРЕДИ ────────────────────────────────────────────
-- Спира, ако колоната от V37 липсва, т.е. кодът още не е деплойнат.

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                    WHERE table_name = 'products' AND column_name = 'manually_categorized') THEN
        RAISE EXCEPTION 'ПРЕКЪСНАТО: колоната manually_categorized липсва. Деплойни миграция V37 и кода преди този скрипт.';
    END IF;
END $$;


-- ─── СЕКЦИЯ B: отчет ПРЕДИ ──────────────────────────────────────────────────

