-- ─── СЕКЦИЯ D: предпазител ──────────────────────────────────────────────────

DO $$
DECLARE
    v_premesteni   int;
    v_v_skriti     int;
    v_bez_flag     int;
BEGIN
    SELECT count(*) INTO v_premesteni FROM products WHERE manually_categorized;
    IF v_premesteni <> 4208 THEN
        RAISE EXCEPTION 'ПРЕКЪСНАТО: очаквани 4208 маркирани продукта, намерени %', v_premesteni;
    END IF;

    -- Нито един преместен продукт да не е попаднал в СКРИТА категория
    SELECT count(*) INTO v_v_skriti
      FROM products p JOIN categories c ON c.id = p.category_id
     WHERE p.manually_categorized AND NOT c.show_flag;
    IF v_v_skriti > 0 THEN
        RAISE EXCEPTION 'ПРЕКЪСНАТО: % преместени продукта са в скрита категория', v_v_skriti;
    END IF;

    -- Всеки преместен продукт трябва да има запазена оригинална категория
    SELECT count(*) INTO v_bez_flag
      FROM products WHERE manually_categorized AND category_id_pre_phase5 IS NULL;
    IF v_bez_flag > 0 THEN
        RAISE EXCEPTION 'ПРЕКЪСНАТО: % продукта без запазена оригинална категория', v_bez_flag;
    END IF;

    RAISE NOTICE '✓ Проверките минаха. Преместени и маркирани продукта: %.', v_premesteni;
END $$;

COMMIT;


-- ─── СЕКЦИЯ E: отчет СЛЕД ───────────────────────────────────────────────────
-- Кофите, които се изпразват. Първата група са коренови категории, държали
-- продукти; втората — подкатегории, в които feed-ът е трупал чужда стока
-- („Видео кабели" с 272 видео карти, „Външни SSD" със 176 вътрешни SSD и т.н.).
-- `vsichki` брои и невидимите, защото точно те са смисълът на този пас.

SELECT c.id, left(c.name_bg, 34) AS kategoriya,
       (SELECT count(*) FROM products p WHERE p.category_id = c.id)  AS vsichki,
       (SELECT count(*) FROM products p WHERE p.category_id = c.id
          AND p.active AND p.show_flag AND p.status='AVAILABLE'
          AND p.deleted=false AND p.image_url<>'')                   AS vidimi_sega
FROM categories c
WHERE c.id IN (1, 22, 54, 58, 72, 78, 99, 127, 153, 167, 211, 230,      -- корени
               131, 321, 235, 86, 56, 179, 62, 166, 6, 15, 966, 50)    -- подкатегории-кофи
ORDER BY 3 DESC;

-- Категориите, които печелят най-много продукти.
SELECT c.id, left(c.name_bg, 34) AS kategoriya, count(*) AS poluchava
FROM products p JOIN categories c ON c.id = p.category_id
WHERE p.manually_categorized
GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 25;


